function renderRoster(t,el){el.replaceChildren();const p=document.createElement('p');const guests=t.members.filter(m=>!m.master);p.textContent=`${t.members.length}/10 competidores • ${guests.filter(m=>m.ready).length}/${guests.length} prontos`;el.append(p);for(const m of t.members){const row=document.createElement('div');row.className='tourRosterRow';row.textContent=m.nick+' — '+(m.master?'MESTRE':m.ready?'PRONTO':'AGUARDANDO');row.dataset.status=m.master||m.ready?'win':'wait';el.append(row);}}
function renderBracket(t,el){el.hidden=false;el.replaceChildren();const title=document.createElement('h3');title.textContent='Chaveamento do campeonato';el.append(title);if(!t.matches.length)return;const names=id=>t.members.find(m=>m.id===id)?.nick||'A definir';const rounds=[];let count=t.members.length;while(count>1){rounds.push(Math.ceil(count/2));count=Math.ceil(count/2);}const board=document.createElement('div');board.className='tourBoard';const width=rounds.length*176+146,height=Math.max(140,rounds[0]*92+38);const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.style.minWidth=width+'px';svg.setAttribute('role','img');svg.setAttribute('aria-label','Chaveamento do campeonato');function node(tag,attrs,text){const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;svg.append(n);return n;}const ypos=(r,i)=>38+(i+.5)*(height-48)/rounds[r];for(let r=0;r<rounds.length;r++){const x=r*176+8;node('text',{x,y:20,fill:'#a7f86d','font-size':13},rounds[r]===1?'FINAL':rounds[r]===2?'SEMIFINAL':`RODADA ${r+1}`);const matches=t.matches.filter(m=>m.round===r+1);for(let i=0;i<rounds[r];i++){const m=matches[i],y=ypos(r,i);if(r+1<rounds.length){const next=ypos(r+1,Math.floor(i/2));node('path',{d:`M${x+140} ${y} H${x+158} V${next} H${x+176}`,stroke:'#667085',fill:'none'});}else node('path',{d:`M${x+140} ${y} H${x+176}`,stroke:'#667085'});for(let j=0;j<2;j++){const id=j?m?.b:m?.a;const won=id&&m?.winner===id,lost=id&&m?.winner&&m.winner!==id,live=m&&t.phase==='playing'&&t.matches[t.current]===m;const color=won?'#a7f86d':lost?'#f87171':live?'#facc15':'#94a3b8';node('rect',{x,y:y-29+j*29,width:140,height:27,rx:5,fill:'#17202d',stroke:color});node('text',{x:x+7,y:y-12+j*29,fill:color,'font-size':11,'text-decoration':lost?'line-through':'none'},id?names(id).slice(0,19):m&&j?'Avanço automático':'A definir');}}}const x=rounds.length*176+8,y=ypos(rounds.length-1,0);node('rect',{x,y:y-28,width:130,height:56,rx:7,fill:'#302918',stroke:'#eab308'});node('text',{x:x+7,y:y-7,fill:'#facc15','font-size':13},'🏆 CAMPEÃO');node('text',{x:x+7,y:y+15,fill:'#facc15','font-size':12},names(t.champion).slice(0,19));board.append(svg);el.append(board);const legend=document.createElement('p');legend.textContent='Verde: classificado · Vermelho: eliminado · Amarelo: disputando · Cinza: aguardando';el.append(legend);}
function floatReaction(emoji){const layer=document.getElementById('reactionFloat');if(!layer)return;const span=document.createElement('span');span.textContent=emoji;span.style.left=(35+Math.random()*30)+'%';layer.append(span);setTimeout(()=>span.remove(),3000);}
function updateReactions(t,socket){const menu=document.getElementById('reactionMenu');const m=t.matches[t.current];menu.hidden=!(t.reactions&&t.phase==='playing'&&m&&![m.a,m.b].includes(socket.id));menu.replaceChildren();if(menu.hidden)return;for(const emoji of ['❤️','🔥','😂','👏','😱','🏆','💀','😡']){const b=document.createElement('button');b.type='button';b.textContent=emoji;b.onclick=()=>socket.emit('tournament:reaction',{id:t.id,emoji});menu.append(b);}}

function renderFinance(t,el,socket,isHost){
 const f=t.finance;if(!f)return;const box=document.createElement('section');box.className='financeBox';const money=c=>(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const add=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;box.append(e);return e;};add('h3','Pix — SIMULAÇÃO');add('p',f.enabled?'Inscrição: '+money(f.fee)+' • Total simulado: '+money(f.total):'Torneio gratuito');const msg=add('p','Nenhum dinheiro real é recebido ou transferido.');
 if(isHost&&t.phase==='waiting'&&!t.members.some(m=>m.paid||m.pending)){const input=document.createElement('input');input.type='number';input.min='0';input.max='1000';input.step='0.01';input.value=(f.fee/100).toFixed(2);input.setAttribute('aria-label','Valor da inscrição simulada em reais');const b=document.createElement('button');b.textContent='Definir inscrição (0 = gratuito)';b.onclick=()=>{const v=Number(input.value);if(!Number.isFinite(v)||v<0||v>1000)return;socket.emit('tournament:finance',{id:t.id,cents:Math.round(v*100)},r=>{if(r?.error)msg.textContent=r.error;});};box.append(input,b);}
 if(f.enabled){for(const m of t.members)add('p',m.nick+' — '+(m.paid?'Pago (simulado)':m.pending?'Processando (simulado)':'Pendente'));const me=t.members.find(m=>m.id===socket.id);if(me&&!me.paid&&t.phase==='waiting'){if(me.payment){const image=document.createElement('img');image.src=PIX_DEMO_IMAGES[me.payment.qr];image.alt='QR fictício, não pagável';image.width=160;image.height=160;image.className='pixDemoQR';box.append(image);add('p','QR de teste — NÃO PAGÁVEL');add('p','Referência: '+me.payment.ref.slice(0,12));add('p','Aguardando confirmação automática em 5 segundos…');}else{const b=add('button','Gerar QR Pix de '+money(f.fee));b.onclick=()=>{b.disabled=true;socket.emit('tournament:paySimulation',{id:t.id},r=>{if(r?.error){msg.textContent=r.error;b.disabled=false;}});};}}}
 if(f.payout){add('p','Premiação: '+money(f.payout.cents)+' • '+(t.members.find(m=>m.id===f.payout.winner)?.nick||'Campeão'));add('p',f.payout.status==='paid'?'Premiação paga (simulação)':f.payout.status==='processing'?'Processando premiação simulada…':'Aguardando solicitação do campeão');if(t.champion===socket.id){const details=document.createElement('details');details.open=true;const summary=document.createElement('summary');summary.textContent='🏆 Receber Pix — área do campeão';details.append(summary);box.append(details);if(f.payout.status==='available'){const label=document.createElement('label');label.textContent='Chave fictícia (não informe dados bancários reais)';const input=document.createElement('input');input.value='TESTE-CAMPEAO';input.maxLength=46;label.append(input);const b=document.createElement('button');b.textContent='Simular recebimento da premiação';b.onclick=()=>{b.disabled=true;socket.emit('tournament:payoutSimulation',{id:t.id,key:input.value.trim()},r=>{if(r?.error){msg.textContent=r.error;b.disabled=false;}});};details.append(label,b);}else{const p=document.createElement('p');p.textContent=f.payout.status==='paid'?'Recebimento confirmado — simulação concluída.':'Aguarde 5 segundos…';details.append(p);}}}el.append(box);
}
